calls.content:
{
  "columns": {
    "shopping_cart_events.visit_id": "방문 세션을 구분하는 고유 ID (ex. 한 번의 쇼핑 세션)",
    "shopping_cart_events.cookie_id": "사용자 고유 식별자(브라우저/기기 단위)",
    "shopping_cart_events.page_id": "방문한 페이지 식별자(상품 상세, 장바구니 등, 의미는 별도 참조 테이블 필요)",
    "shopping_cart_events.event_type": "이벤트 종류(1: 페이지 진입, 2: 상품 장바구니 담기, 3: 상품 제거, 4: 구매 클릭, 5: 결제 완료 등 추정)",
    "shopping_cart_events.sequence_number": "이벤트 발생 순서(각 방문(visit_id) 내에서 1부터 증가)",
    "shopping_cart_events.event_time": "이벤트 발생 시각(YYYY-MM-DD HH:MM:SS.ssssss 형식)"
  },
  "relationships": []
}

{
  "columns": {
    "orders.id": "주문 ID (고유 식별자)",
    "orders.customer_id": "고객 ID (주문한 고객을 식별하는 값)",
    "orders.ordered": "주문일 (주문이 접수된 날짜, 예: 2019-01-15)",
    "orders.delivery": "배송일 (주문이 배송된 날짜, 내용 미확실)"
  },
  "relationships": []
}

{
  "columns": {
    "orderlines.id": "orderlines 테이블의 각 행을 고유하게 식별하는 기본키",
    "orderlines.order_id": "주문을 구분하는 ID, 하나의 주문(order)과 연결됨 (주문 번호)",
    "orderlines.product_id": "상품을 구분하는 ID, 상품(product) 테이블의 기본키와 연결될 가능성 있음 (상품 번호)",
    "orderlines.qty": "해당 상품의 주문 수량 (실수, 예: 110.0개)",
    "orderlines.amount": "해당 상품 총 주문금액 (실수, qty * 단가로 계산된 값)"
  },
  "relationships": [
    "orderlines.order_id = orders.id",   // 추정: 주문 정보 테이블이 있을 경우 연결
    "orderlines.product_id = products.id" // 추정: 상품 정보 테이블이 있을 경우 연결
  ]
}

{
  "columns": {
    "orderlines.id": "주문 상세(라인) 고유 식별자",
    "orderlines.order_id": "주문 고유 식별자 (order 테이블의 id를 참조할 것으로 추정)",
    "orderlines.product_id": "상품 고유 식별자 (product 테이블의 id를 참조할 것으로 추정)",
    "orderlines.qty": "주문한 상품 수량",
    "orderlines.amount": "주문 상세의 금액 (단가 * 수량의 계산값으로 추정, 예시: amount = qty * product.price)"
  },
  "relationships": [
    "orderlines.order_id = orders.id",
    "orderlines.product_id = products.id"
  ]
}

{
  "columns": {
    "airports_data.airport_code": "공항 코드 (국제적으로 3자리 문자열, 예: 'YKS', 'MJZ', 러시아 내 주요 공항식별자)",
    "airports_data.airport_name": "공항명 (영어/러시아어 이름이 포함된 JSON 문자열, 예: {'en': 'Yakutsk Airport', 'ru': 'Якутск'})",
    "airports_data.city": "도시명 (영어/러시아어 도시명이 포함된 JSON 문자열, 예: {'en': 'Yakutsk', 'ru': 'Якутск'})",
    "airports_data.coordinates": "공항 위치의 위도와 경도 (실수 2개를 튜플 형태의 문자열로 저장, 예: '(129.77099609375,62.0932998657226562)')",
    "airports_data.timezone": "공항이 위치한 표준 시간대(리전/도시 형식의 텍스트, 예: 'Asia/Yakutsk')"
  },
  "relationships": []
}

{
  "columns": {
    "flights.flight_id": "개별 항공편의 고유 식별자 (정수, PK 추정)",
    "flights.flight_no": "항공편 번호, 예: 'PG0134' (항공사 코드+숫자형식, 개별 항공편을 식별)",
    "flights.scheduled_departure": "예정 출발 시각 (YYYY-MM-DD HH:MI:SS+TZ 형식)",
    "flights.scheduled_arrival": "예정 도착 시각 (YYYY-MM-DD HH:MI:SS+TZ 형식)",
    "flights.departure_airport": "출발 공항 코드 (예: 'DME'=Moscow Domodedovo, 'VKO'=Moscow Vnukovo, 'SVO'=Moscow Sheremetyevo, 'LED'=St Petersburg, 'SVX'=Ekaterinburg, 'KZN'=Kazan, 'ROV'=Rostov, 'PEE'=Perm, 'JOK'=Yoshkar-Ola, 'SCW'=Syktyvkar 등 IATA 3자리 코드)",
    "flights.arrival_airport": "도착 공항 코드 (예: 'BTK'=Bratsk, 'HMA'=Khanty-Mansiysk, 'AER'=Sochi, 'UFA'=Ufa, 'ULV'=Ulyanovsk, 'KRO'=Kurgan, 'REN'=Orenburg, 'SCW'=Syktyvkar, 'IKT'=Irkutsk, 'MQF'=Magnitogorsk 등 IATA 3자리 코드)",
    "flights.status": "항공편 상태 (예: 'Scheduled'=예정, 'Cancelled'=취소, 'Arrived'=도착완료, 'On Time'=정시출발, 'Delayed'=지연, 'Departed'=출발완료)",
    "flights.aircraft_code": "운항 항공기 코드 (예: '319'=Airbus A319, 'CR2'=Canadair CRJ-200, '763'=Boeing 767-300, 'SU9'=Sukhoi Superjet 100-95, '733'=Boeing 737-300, 'CN1'=Cessna 208 Caravan, '321'=Airbus A321, '773'=Boeing 777-300 ---- IATA, ICAO, 사내 코드 등 추정됨)",
    "flights.actual_departure": "실제 출발 시각 (예: '2017-07-16 09:44:00+03', 또는 '\\N'=출발 미실시/취소)",
    "flights.actual_arrival": "실제 도착 시각 (예: '2017-07-16 10:39:00+03', 또는 '\\N'=미도착/취소)"
  },
  "relationships": [
    // 추론 가능한 다른 테이블이 있으면 예를 들면:
    // "flights.departure_airport = airports.airport_code",
    // "flights.arrival_airport = airports.airport_code",
    // "flights.aircraft_code = aircrafts.aircraft_code"
    // 위 예시는 스키마에 없는 테이블과의 일반적 조인을 명시, 요청된 샘플만으로는 flights 테이블 내에는 직접 관계가 없음
  ]
}

{
  "columns": {
    "retirements.race_id": "경기(레이스) 고유 번호. 예시값: 18, 19, 20 등. 같은 레이스를 식별하는 키로 사용됨.",
    "retirements.driver_id": "드라이버 고유 번호. 예시값: 7, 8, 9 등. 특정 운전자를 식별.",
    "retirements.lap": "리타이어(차량 중단)가 발생한 랩(순환) 번호. 예시값: 56, 54 등. (NULL 가능)",
    "retirements.position_order": "해당 리타이어가 발생한 시점의 순위. 예시값: 7, 8 등. 각 값은 해당 시점의 순위(1등, 2등 등)를 지칭하는 듯 함.",
    "retirements.status_id": "리타이어(중도포기)의 상세 상태를 나타내는 코드값. 예시값: 5, 4, 3 등. (5=Mechanical Problem, 4=Driver Error, 3=Disqualification 등으로 보임. 각 상태는 retirement_type과 대응)",
    "retirements.retirement_type": "리타이어 유형(설명용). 예시값: Retirement (Mechanical Problem), Retirement (Driver Error) 등. 상태에 대한 자세한 설명."
  },
  "relationships": [
    "retirements.race_id = races.race_id",
    "retirements.driver_id = drivers.driver_id",
    "retirements.status_id = status.status_id"
  ]
}

{
  "columns": {
    "access_log.session": "세션 식별자 (범용 문자열, 접속 세션 혹은 로그 구분용)",
    "access_log.user_id": "사용자 식별자 (예: U001, U002, 0CVKaz 등. 실제 사용자임)",
    "access_log.action": "사용자 행동 코드 (예: view=페이지 조회, 기타는 기능/이벤트 코드로 추정)",
    "access_log.stamp": "이벤트 발생 시각 (YYYY-MM-DD HH:MM:SS 형식의 타임스탬프)"
  },
  "relationships": [
    // 샘플 데이터만으로는 join 관계를 유추할 수 있는 다른 테이블 정보가 부족함
  ]
}

{
  "columns": {
    "access_log.session": "세션 아이디 또는 로그인 세션을 구분하는 고유값 (숫자/영문 조합 또는 날짜)",
    "access_log.user_id": "사용자 아이디 (고유 사용자 식별값, 'U001' 등은 전형적, 영문/숫자 조합도 가능)",
    "access_log.action": "유저의 액션 코드 또는 행위명. 'view'는 페이지 조회, 나머지 영문/숫자 조합은 커스텀 이벤트 코드(의미 불확실)",
    "access_log.stamp": "액션 발생 시각 (날짜와 시간, 타임스탬프)"
  },
  "relationships": []
}

{
  "columns": {
    "Subjects.SubjectID": "과목의 고유 식별자 (정수형)",
    "Subjects.CategoryID": "과목이 속한 학문 분야 코드 (예: ACC=Accounting, ART=Art, BIO=Biology, BUS=Business, CHE=Chemistry, CIS=Computer Information Systems, CSC=Computer Science, ECO=Economics, ENG=English, GEG=Geography 등)",
    "Subjects.SubjectCode": "과목 코드 (일반적으로 '카테고리 코드 + 번호' 형태, 예: ACC 210, ART 100 등)",
    "Subjects.SubjectName": "과목명",
    "Subjects.SubjectPreReq": "수강을 위해 필요한 선수과목 코드 또는 조건 (콤마로 여러 과목 및 조건이 나열됨, 예: 'ACC 210', 'BUS 170', 'ENG 101')",
    "Subjects.SubjectDescription": "과목에 대한 상세 설명"
  },
  "relationships": [
    "Subjects.CategoryID = Subjects.SubjectCode(첫 단어)", 
    "Subjects.SubjectCode = Subjects.SubjectPreReq(값이 일치하는 경우)"
  ]
}

{
  "columns": {
    "Categories.CategoryID": "과목 또는 학문 분야를 구분하는 코드 (예시: ACC=Accounting, ART=Art, BIO=Biology, BUS=Business, CHE=Chemistry, CIS=Computer Information Systems, CSC=Computer Science, ECO=Economics, ENG=English, FRE=French)",
    "Categories.CategoryDescription": "카테고리 코드(CategoryID)에 해당하는 학문 분야의 전체 이름",
    "Categories.DepartmentID": "각 카테고리에 속한 부서의 고유 번호 (1 ~ 5 등, 각 숫자가 특정 부서를 의미함)"
  },
  "relationships": [
    // DepartmentID가 다른 테이블에도 존재한다면: "Categories.DepartmentID = 다른테이블.DepartmentID"
    // CategoryID가 다른 테이블에도 존재한다면: "Categories.CategoryID = 다른테이블.CategoryID"
  ]
}

{
  "columns": {
    "pizza_clean_customer_orders.order_id": "고유 주문 번호 (각 주문을 식별하는 PRIMARY KEY 역할)",
    "pizza_clean_customer_orders.customer_id": "주문한 고객의 고유 식별자 (예: 101 = A 고객, 102 = B 고객, ...)",
    "pizza_clean_customer_orders.pizza_id": "주문한 피자의 고유 번호 (예: 1 = 마르게리타, 2 = 페퍼로니 등 피자 종류별 코드)",
    "pizza_clean_customer_orders.exclusions": "제외 요청된 토핑 또는 재료 코드(복수 가능, 쉼표 구분. 예: '4'=올리브, '2,6'=피망, 양파 등)",
    "pizza_clean_customer_orders.extras": "추가 요청된 토핑 또는 재료 코드(복수 가능, 쉼표 구분. 예: '1'=치즈, '1,5'=치즈, 버섯 등)",
    "pizza_clean_customer_orders.order_time": "주문 시간(yyyy-mm-dd hh:mm:ss 포맷)"
  },
  "relationships": [
    "pizza_clean_customer_orders.customer_id = [고객 정보 테이블].customer_id",
    "pizza_clean_customer_orders.pizza_id = [피자 정보 테이블].pizza_id"
  ]
}

{
  "columns": {
    "pizza_recipes.pizza_id": "피자의 고유 번호 (예: 1, 2)",
    "pizza_recipes.toppings": "피자에 사용된 토핑들의 ID를 콤마로 구분한 목록 (예시: 1=토핑1, 2=토핑2, 3=토핑3, 4=토핑4, 5=토핑5, 6=토핑6, 8=토핑8, 10=토핑10 등. 실제 토핑 ID와 이름은 추가 데이터 필요)"
  },
  "relationships": []
}

{
  "columns": {
    "batsman_scored.match_id": "경기 식별자 (예: 335987, 각 경기별로 고유)",
    "batsman_scored.over_id": "이닝 내 오버(Over) 번호 (예: 1~10로 샘플 제공, 각 이닝이 진행되는 순서상의 오버 번호)",
    "batsman_scored.ball_id": "해당 오버 안에서의 볼(Ball) 번호 (예: 1~9, 한 오버는 일반적으로 6개 볼)",
    "batsman_scored.runs_scored": "해당 볼에서 타자가 획득한 점수 (0: 득점 없음, 1: 1점, 2: 2점, 3: 3점, 4: 4점, 5: 5점, 6: 6점)",
    "batsman_scored.innings_no": "이닝 번호 (1: 1st innings, 2: 2nd innings. 보통 한 경기 2회 이닝 진행)"
  },
  "relationships": []
}

{
  "columns": {
    "pizza_get_extras.row_id": "테이블의 고유 식별자",
    "pizza_get_extras.order_id": "주문 식별자 (각 주문을 구분, 여러 row에서 중복 가능)",
    "pizza_get_extras.extras": "추가 주문 항목 코드 (예: 1, 4, 5은 각각 특정 토핑이나 추가품을 의미)",
    "pizza_get_extras.extras_count": "해당 추가 항목이 주문된 수량"
  },
  "relationships": []
}

{
  "columns": {
    "pizza_names.pizza_id": "피자 종류를 식별하는 고유 ID",
    "pizza_names.pizza_name": "피자 이름 (예: Meatlovers, Vegetarian)"
  },
  "relationships": []
}

{
  "columns": {
    "pizza_clean_customer_orders.order_id": "주문 고유 번호 (숫자, 일련번호)",
    "pizza_clean_customer_orders.customer_id": "고객 고유 번호 (예: 101, 102 등, 고객 식별자)",
    "pizza_clean_customer_orders.pizza_id": "피자 고유 번호 (예: 1, 2, 피자 종류 식별자)",
    "pizza_clean_customer_orders.exclusions": "피자에서 뺄 토핑/재료 코드들 (쉼표로 구분된 숫자코드; 예: '4'='특정 토핑 번호', '2,6'='2번, 6번 토핑 제외')",
    "pizza_clean_customer_orders.extras": "피자에 추가할 토핑/재료 코드들 (쉼표로 구분된 숫자코드; 예: '1'='1번 토핑 추가', '1,5'='1번, 5번 토핑 추가')",
    "pizza_clean_customer_orders.order_time": "주문이 접수된 시각 (YYYY-MM-DD HH:MM:SS 형식)"
  },
  "relationships": [
    // 직접적인 테이블 간 조인 관계 정보는 없으나, 일반적으로 다음과 같은 관계를 예상할 수 있음:
    // "pizza_clean_customer_orders.customer_id = customers.customer_id",
    // "pizza_clean_customer_orders.pizza_id = pizza_menu.pizza_id"
  ]
}

{
  "columns": {
    "SalesPersonQuotaHistory.BusinessEntityID": "영업사원 또는 비즈니스 엔터티를 식별하는 고유 ID. 동일한 BusinessEntityID가 여러 날짜에 등장하는 것으로 보아 개인을 대표함.",
    "SalesPersonQuotaHistory.QuotaDate": "해당 할당 쿼터(목표치)가 적용되는 날짜(기준일).",
    "SalesPersonQuotaHistory.SalesQuota": "해당 기간 동안의 영업 목표(쿼터) 금액. 예시값은 통화 단위로 목표 매출 등 추정.",
    "SalesPersonQuotaHistory.rowguid": "글로벌 고유 식별자(GUID)로, 시스템적으로 유일성을 보장하고 레코드 식별에 사용.",
    "SalesPersonQuotaHistory.ModifiedDate": "레코드가 마지막으로 수정된 일시."
  },
  "relationships": [
    // (관계 추론 근거: BusinessEntityID가 다른 테이블의 기본키로 많이 사용)
    "SalesPersonQuotaHistory.BusinessEntityID = SalesPerson.BusinessEntityID",
    "SalesPersonQuotaHistory.BusinessEntityID = Employee.BusinessEntityID"
  ]
}

{
  "columns": {
    "cities.city_id": "도시의 고유 식별자 (정수)",
    "cities.city_name": "도시 이름(영문 소문자, 예: tokyo, delhi 등)",
